const invoiceText = [
  "INVOICE NUMBER: INV-PDF-2026-904",
  "DATE: 2026-10-14",
  "VENDOR: Acme Industrial Automation Corp",
  "ITEM: Industrial Sensor Pack x3 @ 150.00 USD = 450.00 USD",
  "ITEM: DIN Rail Power Supply x2 @ 85.50 USD = 171.00 USD",
  "SUBTOTAL: 621.00 USD",
  "TAX: 49.68 USD",
  "TOTAL: 670.68 USD"
].join("\n");

// Create a valid one-page PDF with embedded text.
const escapePDF = s =>
  s.replace(/\\/g, "\\\\")
   .replace(/\(/g, "\\(")
   .replace(/\)/g, "\\)");

const lines = invoiceText.split("\n");
const commands = ["BT", "/F1 11 Tf", "50 740 Td"];

lines.forEach((line, i) => {
  if (i > 0) commands.push("0 -22 Td");
  commands.push(`(${escapePDF(line)}) Tj`);
});

commands.push("ET");
const stream = commands.join("\n") + "\n";

const objects = [
  "<< /Type /Catalog /Pages 2 0 R >>",
  "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
  "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
  `<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}endstream`,
  "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"
];

let pdf = "%PDF-1.4\n";
const offsets = [0];

objects.forEach((obj, i) => {
  offsets.push(Buffer.byteLength(pdf));
  pdf += `${i + 1} 0 obj\n${obj}\nendobj\n`;
});

const xrefOffset = Buffer.byteLength(pdf);
pdf += `xref\n0 ${objects.length + 1}\n`;
pdf += "0000000000 65535 f \n";

for (let i = 1; i < offsets.length; i++) {
  pdf += String(offsets[i]).padStart(10, "0") + " 00000 n \n";
}

pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\n`;
pdf += `startxref\n${xrefOffset}\n%%EOF\n`;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(pdf, "utf8"),
  "vendor_invoice_INV-904.pdf",
  "application/pdf"
);

return {
  json: {
    fileName: "vendor_invoice_INV-904.pdf",
    sourceChannel: "Supplier_Portal_Upload",
    fileType: "application/pdf"
  },
  binary: {
    data: binaryData
  }
};

const rawText = $input.item.json.text || "";

const getValue = (regex, fallback = "") =>
  rawText.match(regex)?.[1]?.trim() || fallback;

const invoiceNumber = getValue(
  /INVOICE NUMBER:\s*([A-Z0-9-]+)/i,
  "UNKNOWN_INV"
);

const orderDate = getValue(
  /DATE:\s*(\d{4}-\d{2}-\d{2})/i
);

const vendor = getValue(
  /VENDOR:\s*([^\r\n]+)/i,
  "Unknown Vendor"
);

const getAmount = label => {
  const match = rawText.match(
    new RegExp(`^${label}:\\s*([\\d.]+)`, "im")
  );
  return match ? Number(match[1]) : 0;
};

const items = [];

const itemRegex =
  /^ITEM:\s*(.*?)\s+x(\d+)\s+@\s+([\d.]+)\s+USD\s*=\s*([\d.]+)\s+USD/gim;

let match;

while ((match = itemRegex.exec(rawText)) !== null) {
  items.push({
    sku: "PDF-EXTRACTED-SKU",
    description: match[1].trim(),
    quantity: Number(match[2]),
    unitPrice: Number(match[3]),
    total: Number(match[4])
  });
}

return {
  json: {
    sourceType: "PDF_INVOICE",
    orderId: invoiceNumber,
    orderDate: orderDate,
    customer: {
      fullName: vendor,
      email: "billing@acmeindustrial.com",
      phone: "+1-800-555-0199"
    },
    items: items,
    financials: {
      subtotal: getAmount("SUBTOTAL"),
      tax: getAmount("TAX"),
      total: getAmount("TOTAL")
    }
  }
};

return [
  {
    json: {
      orderId: "LEG-8841",
      orderDate: "10/14/2026",
      sourceTimezone: "America/New_York",
      customer: {
        rawName: " jOHn dOE-sMITH ",
        email: "JOHN.DOE@GMAIL.COM ",
        phone: "(555) 019-2834"
      },
      items: [
        {
          sku: "item-01",
          description: "Mechanical Keyboard",
          unitPrice: " $129.99 ",
          quantity: 2
        },
        {
          sku: "item-02",
          description: "Wrist Rest",
          unitPrice: "24.50",
          quantity: 1
        }
      ],
      discountPercent: 10
    }
  },
  {
    json: {
      orderId: "LEG-8842",
      orderDate: "2026-10-15T08:45:00-07:00",
      sourceTimezone: "America/Los_Angeles",
      customer: {
        rawName: "ALICE WONDERLAND",
        email: "alice@adventures.co.uk",
        phone: "+44 20 7946 0919"
      },
      items: [
        {
          sku: "item-09",
          description: "UltraWide Monitor 34-inch",
          unitPrice: "499.00 USD",
          quantity: 1
        },
        {
          sku: "item-12",
          description: "Monitor Arm Mount",
          unitPrice: "$85.00",
          quantity: 2
        }
      ],
      discountPercent: 15
    }
  }
];

const item = $input.item.json;

const rawDate = item.orderDate;
const tz = item.sourceTimezone || 'UTC';

let parsedDate;

if (rawDate.includes('/')) {
  parsedDate = DateTime.fromFormat(
    rawDate.trim(),
    'MM/dd/yyyy',
    { zone: tz }
  );
} else {
  parsedDate = DateTime.fromISO(
    rawDate.trim(),
    { zone: tz }
  );
}

if (!parsedDate.isValid) {
  throw new Error(
    `Invalid order date: ${rawDate}`
  );
}

return {
  json: {
    ...item,
    normalizedDateUtc: parsedDate.toUTC().toISO(),
    displayDate: parsedDate.toFormat(
      'yyyy-MM-dd HH:mm:ss'
    )
  }
};

const item = $input.item.json;

const TAX_RATE = 0.085;
const discountPct = Number(item.discountPercent || 0);

const cleanedItems = (item.items || []).map(line => {
  const cleanPrice = Number(
    String(line.unitPrice).replace(/[^0-9.-]+/g, '')
  ) || 0;

  const qty = Number(line.quantity) || 1;

  return {
    sku: String(line.sku).toUpperCase().trim(),
    description: String(line.description).trim(),
    quantity: qty,
    unitPrice: cleanPrice,
    lineTotal: Number((cleanPrice * qty).toFixed(2))
  };
});

const subtotal = cleanedItems.reduce(
  (sum, line) => sum + line.lineTotal,
  0
);

const discountAmount = Number(
  (subtotal * discountPct / 100).toFixed(2)
);

const taxableAmount = subtotal - discountAmount;

const taxAmount = Number(
  (taxableAmount * TAX_RATE).toFixed(2)
);

const grandTotal = Number(
  (taxableAmount + taxAmount).toFixed(2)
);

const cleanedName = String(
  item.customer?.rawName || ""
)
  .trim()
  .toLowerCase()
  .replace(/\b\w/g, c => c.toUpperCase());

return {
  json: {
    sourceType: "LEGACY_JSON",
    orderId: item.orderId,
    orderDate: item.normalizedDateUtc,
    customer: {
      fullName: cleanedName,
      email: String(item.customer?.email || "")
        .trim()
        .toLowerCase(),
      phone: item.customer?.phone || ""
    },
    items: cleanedItems,
    financials: {
      subtotal: Number(subtotal.toFixed(2)),
      discount: discountAmount,
      tax: taxAmount,
      total: grandTotal
    }
  }
};

const responses = $input.all();

const orders = responses.map(item => {
  const data = item.json.json ?? item.json;

  return {
    transactionId: data.transactionId,
    sourceSystem: data.sourceSystem,
    amountPayable: Number(data.amountPayable || 0),
    status: "POST_SUCCESS"
  };
});

const totalAmount = orders.reduce(
  (sum, order) => sum + order.amountPayable,
  0
);

return [
  {
    json: {
      auditStatus: "COMPLETED",
      processedAt: new Date().toISOString(),
      totalOrders: orders.length,
      totalAmount: Number(totalAmount.toFixed(2)),
      orders: orders
    }
  }
];
